mapper.select:
select * from eval_case_candidate

  and status=#{status}
  and risk=#{risk}

order by discovered_at desc limit #{limit} offset #{offset}

select c.*,
  json_unquote(json_extract((select e.metadata_json from agent_trace_event e where e.run_id=c.source_run_id and e.event_type='ROUTING_DECIDED' order by e.sequence_no asc,e.occurred_at asc limit 1),'$.routeType')) as route_type,
  coalesce(c.source_agent_id,r.agent_id) as finding_agent_id,r.latency_ms as source_latency_ms,
  rv.reviewer as reviewed_by,rv.reviewed_at
from eval_case_candidate c
left join agent_run r on r.id=c.source_run_id
left join eval_case_review rv on rv.id=(select er.id from eval_case_review er where er.candidate_id=c.id order by er.reviewed_at desc,er.id desc limit 1)

  and c.status=#{status}
  and c.risk=#{risk}
  and coalesce(c.detection_source,'RULE_DETECTED')!='MODEL_DETECTED'
  and c.detection_source='MODEL_DETECTED' and c.rule_id not like '%visual%'
  and c.detection_source='MODEL_DETECTED' and c.rule_id like '%visual%'
  and json_unquote(json_extract((select e.metadata_json from agent_trace_event e where e.run_id=c.source_run_id and e.event_type='ROUTING_DECIDED' order by e.sequence_no asc,e.occurred_at asc limit 1),'$.routeType'))=#{routeType}
  and coalesce(c.source_agent_id,r.agent_id)=#{agentId}
  and c.source_run_id=#{sourceRunId}
  and c.discovered_at>=#{discoveredFrom}
  and c.discovered_at<=#{discoveredTo}
  and r.latency_ms>=#{minLatencyMs}
  and r.latency_ms<=#{maxLatencyMs}

order by c.discovered_at desc limit #{limit} offset #{offset}
